--
-- Name: atualizar_alertas_prontos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atualizar_alertas_prontos(op uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM operacoes WHERE id=op FOR UPDATE;
 SELECT operacao_id,produto_id,saldo,meta,meta*percentual_alerta/100 FROM estoque_prontos
 WHERE operacao_id=op AND contagem_informada AND saldo<meta*percentual_alerta/100
 ON CONFLICT(operacao_id,produto_id) WHERE resolvido_em IS NULL DO UPDATE SET
 saldo=EXCLUDED.saldo,meta=EXCLUDED.meta,limite=EXCLUDED.limite,atualizado_em=now()
 WHERE (alertas_prontos.saldo,alertas_prontos.meta,alertas_prontos.limite) IS DISTINCT FROM (EXCLUDED.saldo,EXCLUDED.meta,EXCLUDED.limite);
 UPDATE alertas_prontos a SET resolvido_em=now(),atualizado_em=now()
 WHERE operacao_id=op AND resolvido_em IS NULL AND NOT EXISTS(
 SELECT 1 FROM estoque_prontos e WHERE e.operacao_id=op AND e.produto_id=a.produto_id
 AND e.contagem_informada AND e.saldo<e.meta*e.percentual_alerta/100);
END $$;


--
-- Name: atualizar_alertas_reposicao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atualizar_alertas_reposicao(op uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- Serializa os monitores da mesma operação. Reentrante na transação de estoque.
 PERFORM 1 FROM operacoes WHERE id=op FOR UPDATE;
 SELECT operacao_id,insumo_id,saldo,minimo FROM estoque_reposicao
 WHERE operacao_id=op AND saldo<minimo
 ON CONFLICT(operacao_id,insumo_id) WHERE resolvido_em IS NULL DO UPDATE
 SET saldo=EXCLUDED.saldo,minimo=EXCLUDED.minimo,atualizado_em=now()
 WHERE (alertas_reposicao.saldo,alertas_reposicao.minimo) IS DISTINCT FROM (EXCLUDED.saldo,EXCLUDED.minimo);
 UPDATE alertas_reposicao a SET resolvido_em=now(),atualizado_em=now()
 WHERE a.operacao_id=op AND a.resolvido_em IS NULL AND NOT EXISTS(
  SELECT 1 FROM estoque_reposicao e WHERE e.operacao_id=op AND e.insumo_id=a.insumo_id AND e.saldo<e.minimo);
END $$;


--
-- Name: disparar_alertas_prontos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disparar_alertas_prontos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM atualizar_alertas_prontos(coalesce(NEW.operacao_id,OLD.operacao_id));
 PERFORM atualizar_alertas_reposicao(coalesce(NEW.operacao_id,OLD.operacao_id));
 RETURN NULL;
END $$;


--
-- Name: disparar_alertas_reposicao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disparar_alertas_reposicao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM atualizar_alertas_reposicao(COALESCE(NEW.operacao_id,OLD.operacao_id));
 RETURN NULL;
END $$;


