--
-- Name: estoque_reposicao; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estoque_reposicao AS
 WITH metas AS (
         SELECT r.operacao_id,
            r.insumo_id,
            sum((r.quantidade * (
                CASE
                    WHEN COALESCE(c.controle_prontos, false) THEN GREATEST((0)::bigint, (ep.meta - ep.saldo))
                    ELSE (COALESCE(c.porcoes_por_sabor, 50))::bigint
                END)::numeric)) AS minimo
           FROM (((public.ingredientes r
             JOIN public.produtos p ON (((p.id = r.produto_id) AND (p.operacao_id = r.operacao_id) AND p.ativo)))
             LEFT JOIN public.configuracao_reposicao c ON ((c.operacao_id = r.operacao_id)))
             LEFT JOIN public.estoque_prontos ep ON (((ep.produto_id = p.id) AND (ep.operacao_id = p.operacao_id))))
          GROUP BY r.operacao_id, r.insumo_id
        )
 SELECT i.operacao_id,
    i.id AS insumo_id,
    i.nome,
    i.unidade,
    m.minimo,
    COALESCE(sum(l.saldo) FILTER (WHERE (l.validade >= CURRENT_DATE)), (0)::numeric) AS saldo,
    COALESCE(sum(l.saldo) FILTER (WHERE (l.validade < CURRENT_DATE)), (0)::numeric) AS vencido,
    min(l.validade) FILTER (WHERE ((l.saldo > (0)::numeric) AND (l.validade >= CURRENT_DATE))) AS proxima_validade
   FROM ((metas m
     JOIN public.insumos i ON (((i.id = m.insumo_id) AND (i.operacao_id = m.operacao_id))))
     LEFT JOIN public.lotes l ON (((l.insumo_id = i.id) AND (l.operacao_id = i.operacao_id))))
  GROUP BY i.operacao_id, i.id, i.nome, i.unidade, m.minimo;


