--
-- Name: estoque_prontos _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.estoque_prontos AS
 SELECT p.operacao_id,
    p.id AS produto_id,
    p.nome,
    (count(l.id) > 0) AS contagem_informada,
    COALESCE(sum(l.saldo) FILTER (WHERE (l.validade > now())), (0)::bigint) AS saldo,
    COALESCE(sum(l.saldo) FILTER (WHERE (l.validade <= now())), (0)::bigint) AS vencido,
    min(l.validade) FILTER (WHERE ((l.saldo > 0) AND (l.validade > now()))) AS proxima_validade,
        CASE
            WHEN ((EXTRACT(isodow FROM CURRENT_DATE))::integer = ANY (c.dias_movimento)) THEN c.meta_movimento
            ELSE c.meta_calmo
        END AS meta,
    c.percentual_alerta,
    ((EXTRACT(isodow FROM CURRENT_DATE))::integer = ANY (c.dias_movimento)) AS dia_movimento
   FROM ((public.produtos p
     JOIN public.configuracao_reposicao c ON (((c.operacao_id = p.operacao_id) AND c.controle_prontos)))
     LEFT JOIN public.lotes_prontos l ON (((l.produto_id = p.id) AND (l.operacao_id = p.operacao_id))))
  WHERE p.ativo
  GROUP BY p.id, c.operacao_id, c.meta_movimento, c.meta_calmo, c.dias_movimento, c.percentual_alerta;


